INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1463019-me482', 'stk-acl', 'ME 482', 'info', '{"desc": "السلام عليكم ياشباب\n\nاليوم تواصلت مع الدكتور حسن الوقاد لمادة “ME 482 Mechanical Vibrations”\nحق يغير الوقت ويخلها يومين في الاسبوع بدل ثلاثة ايام السمستر الجاي 162\nالاثنين والاربعاء الساعه 10 او 11\n\nيقول اذا جبت له 10 تواقيع من طلاب لهم رغبة ينزلونها في يوم الاثنين والاربعاء راح يكلم التشيرمان وينزلها ان شاء الله.\n\nالفايبريشن كورس مهم من رائ, ومع الدكتور الوقاد راح يكون سهل جدا ان اشاء االله\n\nفاللي عنده رغبه أو يعرف احد مهتم, ياليت يتواصل معي علشان اقدر اجمع التوقيعات المطلوبة وينزل الكورس باذن الله.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-482-mechanical-vibrations-dr-hassen-ouakad/175388/1", "user": "ACL", "ts": 1480158046000, "tid": 175388, "pn": 1}}', 1480158046000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p946601-me482', 'stk-amat_24', 'ME 482', 'info', '{"desc": "^^\nآسف عزيزي بس الماث اللي درسته دخل من اذن وخرج من الاذن الثانية اول ما خلص الكورس\n\nتطبيق ال202 في كورس الـme482 ،، وصراحة ما وصلت للفهم العميق للدفرنشل اكويشنز الا مع هذا الكورس\nرغم انه الدكتور اللي يدرسنا (د. حوا) ماهو ذاك الشي في الشرح، بس الدفرنشل اكويشنز وصلت بشكل سريع مع التطبيق\n\nوما زال 202 طويل على الفاضي واشوف اننا نتركه لطلاب الفزكس فقط، والمواضيع المهمة منه تضاف الى المواضيع المهمة من 301 وتوضع في كورس واحد مربوط في التطبيق يُدرس من قبل دكاترة قسمنا\n\nبدون التطبيق ، الرياضيات مجرد ارقام ومجاهيل خالية من اي معنى\n\nبالنسبة لوضعي مع الماث،، من 001 الى 201 ما كانت عندي اي مشكلة معاه…\n202 عدته للاسف واخذت B+ المرة الثانية، وخلصت 301", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/113253/18", "user": "amat_24", "ts": 1323719962000, "tid": 113253, "pn": 18}}', 1323719962000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
